        ///   </para>
        ///   <para>
        ///     C++:
        ///     <see href="https://github.com/jrouwe/JoltPhysics/blob/e77f175595e64cb44218cc9d9d56fc365ad0e36a/Jolt/Physics/SoftBody/SoftBodyMotionProperties.h#L140">Jolt/Physics/SoftBody/SoftBodyMotionProperties.h:140</see>
        ///     <br/>
        ///     <c>void SkinVertices(RMat44Arg inCenterOfMassTransform, const Mat44 *inJointMatrices, uint inNumJoints, bool inHardSkinAll, TempAllocator &amp;ioTempAllocator)</c>
        ///   </para>
        /// </summary>
        /// <remarks>
        ///   <code>
        ///     Skin vertices to supplied joints, information is used by the skinned constraints.
        ///     @param inCenterOfMassTransform Value of Body::GetCenterOfMassTransform().
        ///     @param inJointMatrices The joint matrices must be expressed relative to inCenterOfMassTransform.
        ///     @param inNumJoints Indicates how large the inJointMatrices array is (used only for validating out of bounds).
        ///     @param inHardSkinAll Can be used to position all vertices on the skinned vertices and can be used to hard reset the soft body.
        ///     @param ioTempAllocator Allocator.
        ///   </code>
        ///   <para>
        ///     jointMatrices must hold at least one element per joint the skin's inverse bind matrices reference - the
        ///     native count is read from the object itself and a span that doesn't match it throws
        ///     ArgumentOutOfRangeException. The span is only used for the duration of the call. Throws
        ///     InvalidOperationException: "The motion properties have no soft body settings."
        ///   </para>
        /// </remarks>
        public unsafe void SkinVertices(
            in float4x4 centerOfMassTransform,
            ReadOnlySpan<float4x4> jointMatrices,
            bool hardSkinAll,
            TempAllocator tempAllocator
        )
        {
            fixed (float4x4* jointMatrices_fixed = jointMatrices)
            {
                Jolt.PInvoke.SoftBodyMotionProperties_SkinVertices(
                    this,
                    in centerOfMassTransform,
                    jointMatrices_fixed,
                    (uint)jointMatrices.Length,
                    hardSkinAll,
                    tempAllocator,
                    out var _bufferCheck
                );
                if (_bufferCheck == 1)
                    throw new InvalidOperationException("The motion properties have no soft body settings.");
                if (_bufferCheck == 2)
                    throw new ArgumentOutOfRangeException(
                        nameof(jointMatrices),
                        jointMatrices.Length,
                        "Expected at least one element per joint the skin's inverse bind matrices reference."
                    );
            }
        }

